  "usage_notes": [
    {
      "chord_quality": "maj7",
      "function_role": "tonic-diatonic-seventh",
      "narrative": "Carter prescribes maj7 chords as the I and IV members of the diatonic seventh-chord set ('Two major sevenths I and IV'), voiced in open rather than close position to accommodate finger span: 'the third of the chord has been moved an octave higher, and in the second case both the third and fifth have been moved an octave higher.' For voice-leading into the next chord, the bass note should be selected to continue a chromatic line rather than defaulting to the root. Chapter 9, pp. 117-120; Chapter 10, p. 120.",
      "source_principle_ids": [
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:harmonic-movement-system:voice-leading-over-root-position",
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:harmonic-movement-system:chromatic-bass-for-continuity"
      ],
      "source_work_id": "complete-fingerstyle-jazz-guitar-book",
