    },
    {
      "chord_quality": "maj7",
      "function_role": "tonic-open-voicing",
      "narrative": "Carter prescribes open-position voicing as the practical solution for maj7 fingering: close-position seventh chords are defined but immediately redirected -- 'Unless you have long spidery fingers, you are probably more comfortable with these chords in either of the following standard alternate configurations' in which the third is raised an octave, or both third and fifth are raised. Chapter 9, p. 117.",
      "source_principle_ids": [
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:harmonic-movement-system"
      ],
      "source_work_id": "complete-fingerstyle-jazz-guitar-book",
      "references": [
