          "citation": "chapter 14 p.164"
        }
      ],
      "provenance": "extracted",
      "cross_ref": [
        "dom7/turnaround-singer-restraint"
      ],
      "granularity_level": "a",
      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "dom7",
      "function_role": "turnaround-singer-restraint",
      "narrative": "Carter proscribes elaborate dominant-seventh turnaround elaboration when a singer is holding a note through the final two measures: 'About the only restriction is when you are backing a singer who is holding a note through the last two measures. You should then still be accompanying intelligently and not kicking out the jams.' Chapter 14, p. 164.",
      "source_principle_ids": [
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:harmonic-movement-system:intro-must-end-on-v7"
      ],
      "source_work_id": "complete-fingerstyle-jazz-guitar-book",
      "references": [
        {
          "source": "complete-fingerstyle-jazz-guitar-book",
          "citation": "chapter 14 p.164"
        }
      ],
      "provenance": "extracted",
      "polarity": "proscriptive",
      "cross_ref": [
        "dom7/turnaround-gateway"
      ],
      "granularity_level": "h",
      "granularity_name": "idiom-application"
    },
    {
      "chord_quality": "dom7",
      "function_role": "dominant-seventh-rootless-ensemble-voicing",
      "narrative": "Carter prescribes rootless close voicing for dom7 chords in ensemble contexts: 'the accompaniment is voiced so that the harmony moves in alternating pairs of fourths and tritones. The bottom note in each pair alternates between major or minor seventh to major third. There is no explicitly stated root or fifth of the chord. If you play in a group, the bassist will cover roots and fifths.' Chapter 10, p. 129.",
      "source_principle_ids": [
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:harmonic-movement-system:rootless-close-voicing-ensemble"
      ],
      "source_work_id": "complete-fingerstyle-jazz-guitar-book",
      "references": [
        {
          "source": "complete-fingerstyle-jazz-guitar-book",
          "citation": "chapter 10 p.129"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "b",
      "granularity_name": "voicing-floor"
    },
    {
      "chord_quality": "dom7",
      "function_role": "dominant-seventh-cycle-voice-leading",
      "narrative": "In cycle-of-fifths movement, Carter prescribes analyzing dom7-to-dom7 motion voice by voice rather than as root-position block changes. Using C7->F9 as the specimen: 'The middle voice moves by half step from E to Eb. The bottom line travels from C, the root, to A, the third of F9, by Bb, the 7 of the C7 note.' Chapter 13, p. 156.",
      "source_principle_ids": [
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:harmonic-movement-system:voice-leading-over-root-position"
      ],
      "source_work_id": "complete-fingerstyle-jazz-guitar-book",
      "references": [
        {
          "source": "complete-fingerstyle-jazz-guitar-book",
          "citation": "chapter 13 p.156"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "g",
      "granularity_name": "voice-leading"
    },
    {
      "chord_quality": "dom7",
      "function_role": "instant-modulation-borrowed-v7",
      "narrative": "Carter prescribes borrowing V7 from the destination key as the fastest modulation method -- achievable in as little as two beats: 'Presume you have ended a tune on the standard I chord and have used two beats doing it. You are moving to Db. Use the last two beats to borrow V7 (Ab7) from the upcoming new key, Db.' Chapter 14, p. 165.",
      "source_principle_ids": [
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:harmonic-movement-system:ii-v7-i-modulation"
      ],
      "source_work_id": "complete-fingerstyle-jazz-guitar-book",
      "references": [
        {
          "source": "complete-fingerstyle-jazz-guitar-book",
          "citation": "chapter 14 p.165"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "e",
      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "dom7",
      "function_role": "spread-texture-bass-alternation",
      "narrative": "Carter prescribes a specific bass-motion pattern for dom7 chords in spread texture: 'The root bass notes alternate in moving up a fourth and then down a fifth. Each new bass note is a tenth interval from the melody note above.' This produces the idiomatic 'spread' arrangement texture. Chapter 13, p. 157.",
      "source_principle_ids": [
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:harmonic-movement-system:spread-texture-bass-alternation"
      ],
      "source_work_id": "complete-fingerstyle-jazz-guitar-book",
      "references": [
        {
          "source": "complete-fingerstyle-jazz-guitar-book",
          "citation": "chapter 13 p.157"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "f",
      "granularity_name": "rhythmic-placement"
    },
    {
      "chord_quality": "dom7",
      "function_role": "altered-fifth-bass-derivation",
      "narrative": "Carter prescribes a direct alteration rule for aug7 (dom7#5) and dom7b5 bass voicings: the major-scale shortcut for deriving the fifth 'does not automatically work with scales (or chords) that have raised (sharped) or lowered (flatted) fifths.' Instead, read the alteration from the chord name itself. Chapter 5, p. 77.",
      "source_principle_ids": [
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:melody-harmonization-hierarchy-system:altered-fifth-bass-adjustment"
      ],
      "source_work_id": "complete-fingerstyle-jazz-guitar-book",
      "references": [
        {
          "source": "complete-fingerstyle-jazz-guitar-book",
          "citation": "chapter 5 p.77"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "d",
      "granularity_name": "color-tone-policy"
    },
    {
      "chord_quality": "aug7",
      "function_role": "altered-dominant-bass-fifth",
      "narrative": "Carter's rule for aug7 (C7#5) bass voicing: 'If the chord is C7#5, raise the fifth a half step.' The plain major-scale fifth derivation is explicitly forbidden for this chord type. Chapter 5, p. 77.",
      "source_principle_ids": [
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:melody-harmonization-hierarchy-system:altered-fifth-bass-adjustment"
      ],
      "source_work_id": "complete-fingerstyle-jazz-guitar-book",
      "references": [
        {
          "source": "complete-fingerstyle-jazz-guitar-book",
          "citation": "chapter 5 p.77"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "b",
      "granularity_name": "voicing-floor"
    },
    {
      "chord_quality": "dim7",
      "function_role": "ascending-chromatic-connector",
      "narrative": "Carter prescribes the diminished seventh chord as the standard connector for ascending chromatic root movement: 'In many cases the diminished seventh chord is the in-between, the hamburger helper of ascending harmonic movement.' Chapter 10, p. 120.",
      "source_principle_ids": [
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:harmonic-movement-system:diminished-seventh-ascending-connector"
      ],
      "source_work_id": "complete-fingerstyle-jazz-guitar-book",
      "references": [
        {
          "source": "complete-fingerstyle-jazz-guitar-book",
          "citation": "chapter 10 p.120"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "e",
      "granularity_name": "substitution-rules"
    },
    {
      "chord_quality": "dim7",
      "function_role": "half-step-approach-chord",
      "narrative": "Carter prescribes chromatic approach chords -- including dim7 in the ascending direction -- as a recognized harmonic device: 'Approaching a chord from a half step above or below is another accepted way of moving the harmony.' Chapter 15, p. 167.",
      "source_principle_ids": [
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:harmonic-movement-system:chromatic-root-movement"
      ],
      "source_work_id": "complete-fingerstyle-jazz-guitar-book",
      "references": [
        {
          "source": "complete-fingerstyle-jazz-guitar-book",
          "citation": "chapter 15 p.167"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "g",
      "granularity_name": "voice-leading"
    },
    {
      "chord_quality": "maj",
      "function_role": "triad-bass-third-supply",
      "narrative": "Carter prescribes a specific distributional rule for major triads in solo arrangement: 'when the melody is a major or minor third, the bass note is either a root or fifth, and when the melody is other than a third, the third is used in the bass to harmonically identify the chord.' Chapter 5, p. 83.",
      "source_principle_ids": [
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:melody-harmonization-hierarchy-system:third-placement-melody-contains-third"
      ],
      "source_work_id": "complete-fingerstyle-jazz-guitar-book",
      "references": [
        {
          "source": "complete-fingerstyle-jazz-guitar-book",
          "citation": "chapter 5 p.83"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "h",
      "granularity_name": "idiom-application"
    },
    {
      "chord_quality": "min",
      "function_role": "minor-triad-third-supply",
      "narrative": "Carter's third-supply rule applies identically to minor triads: when the melody contains the minor third of the chord, 'no additional third is required -- the melody notes define the major or minor sound of the harmony.' When the melody does not contain the minor third, place the minor third in the bass to establish the chord's identity. Chapter 5, pp. 79-83.",
      "source_principle_ids": [
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:melody-harmonization-hierarchy-system:third-placement-melody-contains-third"
      ],
      "source_work_id": "complete-fingerstyle-jazz-guitar-book",
      "references": [
        {
          "source": "complete-fingerstyle-jazz-guitar-book",
          "citation": "chapter 5 pp.79-83"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "g",
      "granularity_name": "voice-leading"
    },
    {
      "chord_quality": "maj",
      "function_role": "harmonization-thirds-below-free-stroke",
      "narrative": "Carter prescribes free stroke (not rest stroke) as the mandatory technique when harmonizing a major chord's melody with a note a third below, because thirds fall on adjacent strings: 'Since thirds are on adjacent strings, the free stroke must be used.' Chapter 6, p. 91.",
      "source_principle_ids": [
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:melody-harmonization-hierarchy-system"
      ],
      "source_work_id": "complete-fingerstyle-jazz-guitar-book",
      "references": [
        {
          "source": "complete-fingerstyle-jazz-guitar-book",
          "citation": "chapter 6 p.91"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "i",
      "granularity_name": "other"
    },
    {
      "chord_quality": "maj",
      "function_role": "harmonization-sixths-key-note-on-top",
      "narrative": "Carter prescribes a strict voicing rule for sixth-below harmonization of major chords: 'By convention, scales harmonized in sixths have the key note of each scale on top, with the harmony note a sixth below. If the key note were in the bottom position the ear would perceive the scale as being in a minor key rather than a major key.' Chapter 8, p. 108.",
      "source_principle_ids": [
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:melody-harmonization-hierarchy-system:sixths-key-note-on-top"
      ],
      "source_work_id": "complete-fingerstyle-jazz-guitar-book",
      "references": [
        {
          "source": "complete-fingerstyle-jazz-guitar-book",
          "citation": "chapter 8 p.108"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "b",
      "granularity_name": "voicing-floor"
    },
    {
      "chord_quality": "min",
      "function_role": "harmonization-sixths-key-note-on-top",
      "narrative": "Carter's key-note-on-top rule for sixth-below harmonization applies equally to minor chords. Diatonic sixths may imply minor sevenths or ninths; Carter permits adjusting 'the C to D if you wish to keep the sound to a simple Dm chord' when the extension is unwanted. Chapter 8, pp. 104-108.",
      "source_principle_ids": [
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:melody-harmonization-hierarchy-system:sixths-key-note-on-top",
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:melody-harmonization-hierarchy-system:sixths-diatonic-extension-adjustment"
      ],
      "source_work_id": "complete-fingerstyle-jazz-guitar-book",
      "references": [
        {
          "source": "complete-fingerstyle-jazz-guitar-book",
          "citation": "chapter 8 pp.104-108"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "b",
      "granularity_name": "voicing-floor"
    },
    {
      "chord_quality": "min7",
      "function_role": "harmonization-sixth-implies-extension",
      "narrative": "Carter prescribes adjusting sixth-below harmonization when it implies an unwanted seventh or ninth extension on a minor chord: 'the sixth below will be the minor seventh interval C, of the Dm7 chord. The chord symbol above it is a simple triad, Dm. You can change the C to D if you wish to keep the sound to a simple Dm chord.' Chapter 8, p. 104.",
      "source_principle_ids": [
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:melody-harmonization-hierarchy-system:sixths-diatonic-extension-adjustment"
      ],
      "source_work_id": "complete-fingerstyle-jazz-guitar-book",
      "references": [
