          "citation": "chapter 8 p.104"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "d",
      "granularity_name": "color-tone-policy"
    },
    {
      "chord_quality": "dom7",
      "function_role": "walking-bass-chromatic-approach",
      "narrative": "Carter prescribes chromatic approach notes as the defining characteristic of jazz walking bass over dominant seventh chords. Bass-first conception is mandatory -- 'Think bass-plus-chord, not chord-plus-bass' -- because committing to a chord voicing first severely restricts available approach-note paths. Chapter 10, pp. 124, 141.",
      "source_principle_ids": [
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:self-accompaniment-texture-system:bass-first-conception"
      ],
      "source_work_id": "complete-fingerstyle-jazz-guitar-book",
      "references": [
        {
          "source": "complete-fingerstyle-jazz-guitar-book",
          "citation": "chapter 10 p.124"
        },
        {
          "source": "complete-fingerstyle-jazz-guitar-book",
          "citation": "chapter 11 p.141"
        }
      ],
      "provenance": "extracted",
      "granularity_level": "f",
      "granularity_name": "rhythmic-placement"
    },
    {
      "chord_quality": "dom7",
      "function_role": "intro-whole-tone-color",
      "narrative": "Carter prescribes whole-tone scale color as an option for dominant seventh chords specifically in intro construction: the example intro uses 'a little sprinkle of whole-tone scale thrown in at the C+7' before the final resolution. Chapter 14, p. 160.",
      "source_principle_ids": [
        "alan-de-mause:complete-fingerstyle-jazz-guitar-book:harmonic-movement-system:intro-must-end-on-v7"
      ],
      "source_work_id": "complete-fingerstyle-jazz-guitar-book",
      "references": [
